package fr.definiday

import android.animation.ValueAnimator
import android.content.Context
import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.drawable.Animatable2
import android.graphics.drawable.AnimatedVectorDrawable
import android.graphics.drawable.Drawable
import android.graphics.drawable.LayerDrawable
import android.view.ContextThemeWrapper
import android.view.View
import android.view.accessibility.AccessibilityNodeInfo
import android.widget.ImageView
import fr.definiday.Unlocks.Kind

/** Monsieur Glose: drawables generated by design/mascotte/android/make_android.js, dressed by theme overlays. */
object Glose {
    /** The idle life plays this long, then rests on its still frame (WCAG 2.2.2, battery); a tap replays it. */
    const val IDLE_MS = 26_000L
    /** Worn on the head or beside it: cropped from the head icons. */
    private val WORN = setOf(Kind.TETE, Kind.COU, Kind.OBJET)

    /** [res] themed with style Glose then each overlay of [styles] (pelage, pelote, accessoire). A layered pose (GloseLayers) is a
     *  LayerDrawable of its body parts and of the accessory pieces whose gate one of [styles] opens, in drawing order. */
    fun drawable(ctx: Context, res: Int, styles: List<Int> = emptyList()): Drawable {
        val t = ContextThemeWrapper(ctx, R.style.Glose)
        styles.forEach { t.theme.applyStyle(it, true) }
        val layers = GloseLayers.layers[res] ?: return t.getDrawable(res)!!
        val open = GloseLayers.gates.filter { it.first in styles }.map { it.second }
        return LayerDrawable(layers.filter { it.first.isEmpty() || it.first in open }.map { t.getDrawable(it.second)!! }.toTypedArray())
    }

    /** The animated layers of [d] (itself when it is one AVD). */
    private fun avds(d: Drawable?) = (if (d is LayerDrawable) (0 until d.numberOfLayers).map(d::getDrawable) else listOf(d)).filterIsInstance<AnimatedVectorDrawable>()

    /** The user's choice (pose, pelage, pelote, one item or "" per accessory slot), each falling back to the default unless unlocked and of that slot.
     *  Prefs.gloseAcc holds the worn accessories, comma-separated (a single id before the slots existed). */
    fun choice(p: Prefs): Map<Kind, String> {
        val ok = p.unlocked + Unlocks.of(emptyMap())
        fun fits(kind: Kind, id: String) = id in ok && Unlocks.byId[id]?.kind?.slot == kind
        fun pick(kind: Kind, id: String, default: String) = if (fits(kind, id)) id else default
        val worn = p.gloseAcc.split(',')
        return mapOf(Kind.POSE to pick(Kind.POSE, p.glosePose, "assis"), Kind.PELAGE to pick(Kind.PELAGE, p.glosePelage, "tigre"),
            Kind.PELOTE to pick(Kind.PELOTE, p.glosePelote, "bordeaux")) + Unlocks.ACC.associateWith { k -> worn.firstOrNull { fits(k, it) } ?: "" }
    }

    fun save(p: Prefs, c: Map<Kind, String>) {
        p.glosePose = c.getValue(Kind.POSE); p.glosePelage = c.getValue(Kind.PELAGE)
        p.glosePelote = c.getValue(Kind.PELOTE); p.gloseAcc = Unlocks.ACC.mapNotNull { c[it]?.ifEmpty { null } }.joinToString(",")
    }

    fun pose(c: Map<Kind, String>) = Unlocks.byId[c[Kind.POSE]]?.takeIf { it.kind.slot == Kind.POSE }?.res ?: R.drawable.glose_assis

    /** Main-screen pose: asleep in his cup from 21:00 (local time) once unlocked, else the chosen pose. */
    fun mainPose(p: Prefs, hour: Int = java.time.LocalTime.now().hour) =
        if (hour >= 21 && "soir" in p.unlocked) R.drawable.glose_soir else pose(choice(p))

    /** Theme overlays of a choice. A binding or a frame goes before the pelage, so that a dark pelage keeps its bordeaux base. */
    fun styles(c: Map<Kind, String>) = c.entries.sortedBy { it.key != Kind.LIVRE && it.key != Kind.YEUX }
        .mapNotNull { Unlocks.byId[it.value]?.style }.filter { it != 0 }

    /** Glose showing one collection item on top of choice [c] (empty = defaults): its pose, or wearing it. */
    fun preview(ctx: Context, item: Unlocks.Item, c: Map<Kind, String> = emptyMap()): Drawable {
        val with = c + (item.kind.slot to item.id)
        return drawable(ctx, pose(with), styles(with))
    }

    /** The user's Glose in pose [res] ([accessory] false for the head icons, which crop hats and quills). */
    fun mine(ctx: Context, res: Int, accessory: Boolean = true, extra: List<Int> = emptyList()): Drawable {
        val c = choice(Prefs(ctx))
        return drawable(ctx, res, styles(if (accessory) c else c - WORN) + extra)
    }

    /** (Re)starts the view's animation from the beginning for [IDLE_MS], then rests on the still frame (every loop ends where it began);
     *  stays the still image when animations are off (settings, battery saver): no reset() then, it would rewind the thread to before it
     *  writes and the "le fil écrit…" poses would lose their word. The pending stop lives in the view's tag. */
    fun play(v: ImageView) {
        val d = avds(v.drawable).ifEmpty { return }
        if (paused || !ValueAnimator.areAnimatorsEnabled()) return
        d.forEach { it.reset(); it.start() } // all layers in the same frame: they share their timeline
        v.removeCallbacks(v.tag as? Runnable)
        v.tag = Runnable { d.forEach { it.stop() } }.also { v.postDelayed(it, IDLE_MS) }
    }

    /** The idle life paused by the user ([pausable]), for every Glose until resumed or the app restarts: [play] leaves the still.
     *  Taps still make him react (the user asks for that motion), then he rests. WCAG 2.2.2. */
    var paused = false

    /** A long press on [v], or its TalkBack action « Mettre en pause » / « Reprendre » (the long-press action, relabelled),
     *  pauses or resumes the idle life. No new visible control. When animations are off there is nothing to pause: no action. */
    fun pausable(v: ImageView) {
        v.setOnLongClickListener {
            if (!ValueAnimator.areAnimatorsEnabled()) return@setOnLongClickListener false
            paused = !paused
            if (paused) stop(v) else play(v)
            true
        }
        v.accessibilityDelegate = object : View.AccessibilityDelegate() {
            override fun onInitializeAccessibilityNodeInfo(host: View, info: AccessibilityNodeInfo) {
                super.onInitializeAccessibilityNodeInfo(host, info)
                val long = AccessibilityNodeInfo.AccessibilityAction.ACTION_LONG_CLICK
                if (!ValueAnimator.areAnimatorsEnabled()) { info.removeAction(long); info.isLongClickable = false; return }
                info.addAction(AccessibilityNodeInfo.AccessibilityAction(long.id, host.context.getString(if (paused) R.string.glose_resume else R.string.glose_pause)))
            }
        }
    }

    /** Stops the animation and cancels what was pending: the timed stop, the return to idle of [once]. */
    fun stop(v: ImageView) {
        v.removeCallbacks(v.tag as? Runnable)
        avds(v.drawable).forEach { it.clearAnimationCallbacks(); it.stop() }
    }

    /** Plays the one-shot [res] (R.drawable.glose_icone_hoche: nods; glose_icone_penche: tilts the head, curious) on [v],
     *  then shows [idle] (e.g. R.drawable.glose_icone_vd) and [play]s it. Nothing when animations are off: the still stays.
     *  [accessory] false for the head icons; [dress] builds both drawables. A second call replaces the first; [stop] (onPause) cancels the return. */
    fun once(v: ImageView, res: Int, idle: Int, accessory: Boolean = true, dress: (Int) -> Drawable = { mine(v.context, it, accessory) }) {
        if (!ValueAnimator.areAnimatorsEnabled()) return
        stop(v)
        val d = dress(res)
        val layers = avds(d)
        var left = layers.size // back to idle once every animated layer has ended
        layers.forEach { a -> a.registerAnimationCallback(object : Animatable2.AnimationCallback() {
            override fun onAnimationEnd(x: Drawable) {
                a.clearAnimationCallbacks()
                if (--left > 0) return
                v.setImageDrawable(dress(idle))
                play(v)
            }
        }) }
        v.setImageDrawable(d)
        layers.forEach { it.start() }
    }

    /** Taps on Glose ([next], clock injected for tests): a tap within [QUIET_MS] of the last reaction, or [SPECIAL_QUIET_MS] of a special, is ignored
     *  (no restart mid-gesture) and neither counts nor breaks the streak; [STREAK] accepted taps, each within [STREAK_MS] of the previous, make a special. */
    class Taps(private val now: () -> Long = android.os.SystemClock::uptimeMillis) {
        private var quiet = Long.MIN_VALUE
        private var last = Long.MIN_VALUE / 2
        private var streak = 0

        /** Suffix of the reaction drawable to play ("_tap", "_special"), or null when ignored. */
        fun next(): String? {
            val t = now()
            if (t < quiet) return null
            streak = if (t - last <= STREAK_MS) streak + 1 else 1
            last = t
            if (streak < STREAK) { quiet = t + QUIET_MS; return "_tap" }
            streak = 0; quiet = t + SPECIAL_QUIET_MS
            return "_special"
        }

        companion object {
            const val STREAK = 4
            const val STREAK_MS = 1500L
            const val QUIET_MS = 700L // glose_*_tap lasts 600 ms (design/mascotte/android/reactions.js)
            const val SPECIAL_QUIET_MS = 3000L // glose_*_special lasts 1800 ms, then a calm
        }
    }

    /** A tap on [v] showing [pose] (dressed by [dress]): light haptic, the pose's reaction glose_<pose>_tap / _special, then its idle life.
     *  Haptic only when animations are off ([once] leaves the still). Nothing is announced: TalkBack focus stays where it is. */
    fun tap(v: ImageView, taps: Taps, pose: Int, dress: (Int) -> Drawable = { mine(v.context, it) }) {
        val suffix = taps.next() ?: return
        v.performHapticFeedback(android.view.HapticFeedbackConstants.CONTEXT_CLICK)
        Sounds.play(v.context, if (suffix == "_special") Sounds.PURR else Sounds.MRR) // silent unless « Sons » is on
        val r = v.resources // by name: needs the resources kept (no shrinkResources); GloseTest checks that every pose has both
        val res = r.getIdentifier(r.getResourceEntryName(pose) + suffix, "drawable", v.context.packageName)
        if (res != 0) once(v, res, pose, dress = dress) else play(v)
    }

    /** Still image (notifications, tests): the drawable fitted and centred in a w x h bitmap. */
    fun bitmap(d: Drawable, w: Int, h: Int): Bitmap {
        val b = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        val s = minOf(w, h)
        d.apply { setBounds((w - s) / 2, (h - s) / 2, (w + s) / 2, (h + s) / 2) }.draw(Canvas(b))
        return b
    }
}
